mapper.update:
UPDATE settlement_participant
SET pay_status = 'REPORTED',
    reported_at = NOW()
WHERE id = #{id}
  AND settlement_id = #{settlementId}
  AND token_hash = #{tokenHash}
  AND pay_status = 'UNPAID'

UPDATE settlement_participant
SET pay_status = 'UNPAID',
    reported_at = NULL
WHERE id = #{id}
  AND settlement_id = #{settlementId}
  AND token_hash = #{tokenHash}
  AND pay_status = 'REPORTED'

UPDATE settlement_participant
SET pay_status = 'CONFIRMED',
    confirmed_at = NOW()
WHERE id = #{id}
  AND settlement_id = #{settlementId}
  AND pay_status = 'REPORTED'
